A(E("沼泽大蚊","European Crane Fly","Tipula paludosa","潮湿草地及沼泽","幼虫取食植物根茎,成虫取食花蜜","体长约3厘米","0.1-0.2克",0.03,"无危(LC)","🪰","体细长,足极长而脆弱,飞行缓慢,常被误认为巨型蚊子,但成虫不叮咬,取食花蜜,幼虫在潮湿土壤中取食植物根茎。","A photorealistic macro photograph of a European Crane Fly (Tipula paludosa), slender crane fly with extremely long fragile legs, resting on a grass blade in a damp meadow, National Geographic style."))
A(E("黑腹果蝇","Common Fruit Fly","Drosophila melanogaster","果园、发酵水果及实验室","取食发酵水果和酵母","体长约0.3厘米","0.001-0.002克",0.003,"无危(LC)","🪰","小型蝇类,红眼黄褐色,腹背有黑色环纹,是遗传学研究最重要的模式生物,繁殖快,饲养容易,多项诺贝尔奖研究以它为对象。","A photorealistic macro photograph of a Common Fruit Fly (Drosophila melanogaster), tiny yellow-brown fruit fly with red eyes and black-ringed abdomen, on a rotting banana slice, National Geographic style."))
A(E("中华斑虻","Chinese Deer Fly","Chrysops sinensis","牧场、林缘及溪流边","雌虫叮咬牲畜,雄虫取食花蜜","体长约1.2厘米","0.05-0.1克",0.012,"无危(LC)","🪰","体黄褐色,翅面有云雾状斑纹,复眼巨大带金属光泽,雌虻叮咬牲畜和人的皮肤,雄虻取食花蜜,是牧场常见的大型虻类。","A photorealistic macro photograph of a Chinese Deer Fly (Chrysops sinensis), deer fly with large golden-green eyes and cloud-patterned wings, perched on a blade of grass near a pasture, National Geographic style."))
A(E("黑带食蚜蝇","Marmalade Hoverfly","Episyrphus balteatus","花田、菜园及草地","幼虫捕食蚜虫,成虫吸食花蜜","体长约1厘米","0.02-0.04克",0.01,"无危(LC)","🪰","外形酷似蜜蜂的蝇类,腹部有黑黄相间条纹,常在花丛中悬停,幼虫捕食蚜虫,是农田中重要的天敌昆虫,成虫帮助传粉。","A photorealistic macro photograph of a Marmalade Hoverfly (Episyrphus balteatus), hoverfly with black-and-yellow striped abdomen, hovering beside an orange flower, National Geographic style."))
A(E("羽摇蚊","Feathered Midge","Chironomus plumosus","湖泊、池塘等静水水域","幼虫取食水底有机物,成虫不取食","体长约0.8厘米","0.01-0.02克",0.008,"无危(LC)","🪰","体细长,足长,雄虫触角呈羽毛状,不叮人不吸血,常在水面成群飞舞,幼虫红色俗称红虫,是水生态监测的重要指示生物。","A photorealistic macro photograph of a Feathered Midge (Chironomus plumosus), slender midge with feathery male antennae, resting on a water surface near red larvae, National Geographic style."))

# ============ 半翅目 (12) ============
A(E("蟪蛄","Kaempfer's Cicada","Platypleura kaempferi","树林及果园","若虫吸食树根汁液,成虫吸食树液","体长约2.5厘米","1-2克",0.025,"无危(LC)","🪰","小型蝉,体褐色带绿色斑纹,翅透明有褐色斑,盛夏时节在树林中鸣叫,声音细弱连绵,幼虫在地下吸食树根汁液数年。","A photorealistic macro photograph of a Kaempfer's Cicada (Platypleura kaempferi), small brown cicada with green markings and transparent spotted wings, clinging to a tree trunk, National Geographic style."))
A(E("蒙古寒蝉","Mongolian Cicada","Meimuna mongolica","城市行道树及山林","若虫吸食树根汁液,成虫吸食树液","体长约3厘米","1.5-3克",0.03,"无危(LC)","🪰","中型蝉,体灰绿色带黑色斑纹,秋季鸣叫声音嘹亮,常见于城市行道树,幼虫在地下生活数年,羽化后仅存活数周。","A photorealistic macro photograph of a Mongolian Cicada (Meimuna mongolica), medium gray-green cicada with black markings and translucent wings, on a city street tree, National Geographic style."))
A(E("棉蚜","Cotton Aphid","Aphis gossypii","棉田及瓜类作物上","群集吸食植物汁液","体长约0.2厘米","不足0.001克",0.002,"无危(LC)","🪰","体小,淡黄色至深绿色,群集于棉花等植物嫩梢和叶背吸食汁液,繁殖极快,分泌蜜露引发煤污病,是重要的农业害虫。","A photorealistic macro photograph of a Cotton Aphid (Aphis gossypii), tiny pale yellow-green aphids clustered on a cotton shoot with an ant nearby, National Geographic style."))
A(E("桃蚜","Green Peach Aphid","Myzus persicae","桃树、蔬菜及花卉上","群集吸食植物汁液","体长约0.2厘米","不足0.001克",0.002,"无危(LC)","🪰","体小,绿色或粉红色,寄主范围极广,取食桃树、蔬菜等数百种植物,传播植物病毒病,是分布最广的蚜虫之一。","A photorealistic macro photograph of a Green Peach Aphid (Myzus persicae), small green and pink aphids on the underside of a peach leaf with dewdrops, National Geographic style."))
A(E("荔蝽","Lychee Giant Stink Bug","Tessaratoma papillosa","荔枝、龙眼果园","吸食果实和嫩梢汁液","体长约2.5厘米","1-2克",0.025,"无危(LC)","🪰","大型蝽象,体黄褐色,老熟若虫体色鲜艳,遇敌时喷射臭液,吸食荔枝、龙眼果实汁液,是华南地区重要的果树害虫。","A photorealistic macro photograph of a Lychee Giant Stink Bug (Tessaratoma papillosa), large brown stink bug with yellow markings, on a lychee fruit cluster, National Geographic style."))
A(E("麻皮蝽","Yellow-spotted Stink Bug","Erthesina fullo","城市绿化带及果园","吸食树木和果实汁液","体长约2厘米","0.5-1克",0.02,"无危(LC)","🪰","体灰褐色,背面有细密刻点,前胸背板有黄色细边,臭腺发达,受惊时散发臭味,取食多种树木和果树,常见于城市绿化带。","A photorealistic macro photograph of a Yellow-spotted Stink Bug (Erthesina fullo), gray-brown stink bug with dense punctures and a yellow lateral line, on a tree trunk, National Geographic style."))
A(E("水黾","Common Water Strider","Aquarius paludum","池塘、湖泊等静水水面","捕食落水的小型昆虫","体长约1.5厘米","0.1-0.2克",0.015,"无危(LC)","🪰","体细长,足极长,利用水的表面张力在水面滑行,如水上漂的精灵,捕食落水的昆虫,是池塘水面的常见居民,足部有拒水细毛。","A photorealistic macro photograph of a Common Water Strider (Aquarius paludum), slender water strider with long legs dimpling the water surface, skating across a pond with reflected sky, National Geographic style."))
A(E("大田鳖","Giant Water Bug","Kirkaldyia deyrolli","稻田、池塘等静水水域","捕食小鱼、蝌蚪等小型水生动物","体长约6厘米","3-6克",0.06,"近危(NT)","🪰","大型水生昆虫,体扁平暗褐色,前足镰刀状,捕食小鱼、蝌蚪等小型水生动物,雄虫背负卵块孵化,是水田中的顶级捕食者。","A photorealistic macro photograph of a Giant Water Bug (Kirkaldyia deyrolli), large flat brown water bug with raptorial front legs, male carrying eggs on its back, in shallow pond water, National Geographic style."))
A(E("日本蝎蝽","Water Scorpion","Laccotrephes japonensis","静水池塘及水沟","伏击捕食小型水生动物","体长约4厘米","1-2克",0.04,"无危(LC)","🪰","体暗褐色,前足镰刀状,尾部有细长呼吸管,形似蝎子,栖息于静水中,捕食小型水生动物,是池塘中的伏击猎手。","A photorealistic macro photograph of a Water Scorpion (Laccotrephes japonensis), dark brown water scorpion with pincer-like front legs and a long breathing tube, in still pond water among reeds, National Geographic style."))
A(E("斑衣蜡蝉","Spotted Lanternfly","Lycorma delicatula","臭椿、葡萄及果园","吸食树木汁液","体长约2厘米","0.3-0.6克",0.02,"无危(LC)","🪰","体灰褐色,后翅鲜红色带黑斑,飞行时红黑相间十分醒目,若虫体白色带黑点,群集吸食臭椿等树木汁液,是常见的观赏性害虫。","A photorealistic macro photograph of a Spotted Lanternfly (Lycorma delicatula), lanternfly with gray forewings and bright red hindwings with black spots, wings spread on a tree trunk, National Geographic style."))
A(E("沫蝉","Meadow Spittlebug","Philaenus spumarius","草地及农田","若虫吸食植物汁液","体长约0.6厘米","0.02-0.05克",0.006,"无危(LC)","🪰","体黄褐色,若虫分泌泡沫包裹身体躲避天敌,俗称吹泡虫,泡沫如唾沫挂在草茎上,成虫善于跳跃,取食多种草本植物汁液。","A photorealistic macro photograph of a Meadow Spittlebug (Philaenus spumarius), brown spittlebug nymph surrounded by white foam bubbles on a grass stem, National Geographic style."))
A(E("悬铃木方翅网蝽","Sycamore Lace Bug","Corythucha ciliata","城市悬铃木行道树","群集吸食叶背汁液","体长约0.3厘米","不足0.001克",0.003,"无危(LC)","🪰","体极小,翅透明呈网状花纹,群集于悬铃木叶背吸食汁液,造成叶片枯黄,是入侵性害虫,近年在我国城市迅速扩散。","A photorealistic macro photograph of a Sycamore Lace Bug (Corythucha ciliata), tiny lace bug with transparent netted wings, group on the underside of a plane tree leaf, National Geographic style."))

# ============ 直翅目 (12) ============
A(E("优雅蝈螽","Chinese Bush Cricket","Gampsocleis gratiosa","草丛、灌丛及农田","取食昆虫和植物嫩叶","体长约5厘米","2-4克",0.05,"无危(LC)","🦗","体翠绿色,翅短,雄虫翅摩擦发出响亮叫声,俗称蝈蝈,是深受喜爱的鸣虫,取食昆虫和植物嫩叶,笼养历史悠久。","A photorealistic macro photograph of a Chinese Bush Cricket (Gampsocleis gratiosa), bright green bush cricket with long antennae, singing on a vine leaf in morning light, National Geographic style."))
