# ---------- 校验 ----------
def check():
    errs = []
    names = [x['name'] for x in D]
    scis = [x['scientificName'] for x in D]
    if len(D) != 120: errs.append("数量=%d(应为120)" % len(D))
    dup_name = [n for n in set(names) if names.count(n) > 1]
    dup_sci = [s for s in set(scis) if scis.count(s) > 1]
    if dup_name: errs.append("重复中文名:" + str(dup_name))
    if dup_sci: errs.append("重复学名:" + str(dup_sci))
    forbid = {"中华蜜蜂","帝王蝶","枯叶蝶","柑橘凤蝶","乌桕大蚕蛾","独角仙","锹甲","萤火虫","中华大刀螳","碧伟蜓","黑蚱蝉","斗蟋","东亚飞蝗","日本弓背蚁","七星瓢虫","竹节虫","吉丁虫","家蚕"}
    hit = [n for n in names if n in forbid]
    if hit: errs.append("与已有昆虫重复:" + str(hit))
    for i, e in enumerate(D):
        if not (40 <= len(e['description']) <= 80): errs.append("[%d]%s 描述字数=%d" % (i+1, e['name'], len(e['description'])))
        p = e['imagePrompt']
        if not (p.startswith("A photorealistic macro photograph of a ") or p.startswith("A photorealistic macro photograph of an ")): errs.append("[%d]%s 提示词开头错误" % (i+1, e['name']))
        if not p.endswith("National Geographic style."): errs.append("[%d]%s 提示词结尾错误" % (i+1, e['name']))
        if 'blood' in p.lower() or 'Blood' in p: errs.append("[%d]%s 提示词含敏感词" % (i+1, e['name']))
        if e['category'] != "昆虫类": errs.append("[%d]%s category错误" % (i+1, e['name']))
        if not re.match(r'^[A-Z][a-z]+ [a-z]+$', e['scientificName']): errs.append("[%d]%s 学名格式可疑:%s" % (i+1, e['name'], e['scientificName']))
    return errs

# ---------- 打印计划清单 ----------
print("=" * 70)
print("计划清单(共%d种):序号. 中文名 拉丁学名 (英文名)" % len(D))
print("=" * 70)
for i, e in enumerate(D, 1):
    print("%3d. %s  %s  (%s)" % (i, e['name'], e['scientificName'], e['englishName']))

errs = check()
print("-" * 70)
if errs:
    print("!! 校验发现 %d 个问题:" % len(errs))
    for x in errs: print("  - " + x)
    sys.exit(1)
print("校验通过:120种,无重复,描述40-80字,提示词格式正确,无敏感词。")

